	title 'QD Slices            GS ROM 2.0'*****************************************************************			   **              SLICES		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	include 'all.macros'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:CORE.GLOBALS1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:SLICE.EQUS';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT ShiftOut	IMPORT ShiftStay	IMPORT xShiftOut	IMPORT xShiftStay;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY bEndOfChute	ENTRY bRazorMove	ENTRY fEndOfChute	ENTRY fRazorMove;                COPY SLICES/SLICES****************************************************************** Slices** These are the lowest level pixel transfer routines.  They	copy* pixels from one scan line to another using an appropriate* transfer mode.** Parameters are passed on "ZeroPage" and in the overflow*   flag. (The overflow flag is used to	decide whether to*   invert the source--set for invert, clear for leave*   alone.)* A predraw routine	must set up "ZeroPage" and the overflow*   flag.** The routines do not use shift tables.	 Instead I use the two* shift subroutines.  This is faster than using shift tables* and working only a byte at a time.** The routines can handle scan lines as	long as 32K.  They do not* care about scan line width and will overflow into next scan line* if told to.** The routines starting with "F" paint forwards (left to right)* while routines starting with "B" paint backwards (right to left).*****************************************************************	EXPORT FCopySliceFCopySlice	PROC*              using CoreDATA	stz ShiftTemp	; Zero this for later use	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDestSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	sta ThisWord	; save for later	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestIndex	bmi BumpIndexes	; again if it was neg then special	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	sta ThisWord	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	sta (DestRef),y	; and store it.BumpIndexes		; 	lda ShiftTemp2	sta ShiftTemp	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP	EXPORT FOrSliceFOrSlice	PROC*              using CoreDATA	stz ShiftTemp	; Zero this for later use	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined maskSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	sta ThisWord	; save for later	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	bmi BumpIndexes	; the special case again	ora (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	sta ThisWord	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	ora (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	lda ShiftTemp2	sta ShiftTemp	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP	EXPORT FXORSliceFXORSlice	PROC*              using CoreDATA	stz ShiftTemp	; Zero this for later use	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined maskSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	sta ThisWord	; save for later	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	bmi BumpIndexes	; special case	eor (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	sta ThisWord	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	lda ShiftTemp2	sta ShiftTemp	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP	EXPORT FBICSliceFBICSlice	PROC*              using CoreDATA	stz ShiftTemp	; Zero this for later use	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined maskSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	sta ThisWord	; save for later	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	bmi BumpIndexes	; special case	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	sta ThisWord	iny	iny	sty SrcIndex	jsl ShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl ShiftStay	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	lda ShiftTemp2	sta ShiftTemp	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP;                COPY SLICES/BACK.SLICES****************************************************************** Get Word* ShiftStay and save it** dec SrcIndex* dec SrcIndex** Get Word* ShiftOut* Or with Saved ShiftStay* Save At Dest** Dec DestIndex* Dec DestIndex** Compare DestIndex	with FirstWord*       beq LeftEdge*       bcs Loop**       bra AllDone** Change History* 8/6/87 GCP   Now use x reg to hold HowFarToShift*****************************************************************	EXPORT BFCopySliceBFCopySlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	lda [SrcRef],y	sta ThisWord	dey	dey	sty SrcIndex	; initialize index here	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masks	ldx HowFarToShift	; set up x reg for shift callsLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDest	lda ThisWord	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestIndex	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	lda ThisWord	; get from before	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP	EXPORT BFORSliceBFORSlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	lda [SrcRef],y	sta ThisWord	dey	dey	sty SrcIndex	; initialize index here	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masksLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	lda ThisWord	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	ora (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	lda ThisWord	; get from before	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	ora (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP	EXPORT BFXORSliceBFXORSlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	lda [SrcRef],y	sta ThisWord	dey	dey	sty SrcIndex	; initialize index here	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masksLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	lda ThisWord	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	eor (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	lda ThisWord	; get from before	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP	EXPORT BFBICSliceBFBICSlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	lda [SrcRef],y	sta ThisWord	dey	dey	sty SrcIndex	; initialize index here	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masksLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	lda ThisWord	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	lda ThisWord	; get from before	jsl xShiftStay	sta ShiftTemp	; save it	ldy SrcIndex	lda [SrcRef],y	; get prior word	sta ThisWord	; save for later	dey	dey	sty SrcIndex	jsl xShiftOut	ora ShiftTemp	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP;                COPY SLICES/FSLICES****************************************************************** fSlices** These are the lowest level pixel transfer routines.  They	copy* pixels from one scan line to another using an appropriate* transfer mode without shifting.  They	are only called if no* shifting is needed.** Parameters are passed on "ZeroPage" and in the overflow*   flag. (The overflow flag is used to	decide whether to*   invert the source--set for invert, clear for leave*   alone.)* A predraw routine	must set up "ZeroPage" and the overflow*   flag.** The routines do not use shift tables.	 Instead I use the two* shift subroutines.  This is faster than using shift tables* and working only a byte at a time.** The routines can handle scan lines as	long as 32K.  They do not* care about scan line width and will overflow into next scan line* if told to.** The routines starting with "F" paint forwards (left to right)* while routines starting with "B" paint backwards (right to left).*****************************************************************	EXPORT fFCopySlicefFCopySlice	PROC*              using CoreDATA	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDestSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestIndex	bmi BumpIndexes	; again if it was neg then special	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	sta (DestRef),y	; and store it.BumpIndexes		; 	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP	EXPORT fFOrSlicefFOrSlice	PROC*              using CoreDATA	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined maskSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	bmi BumpIndexes	; the special case again	ora (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	ora (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP	EXPORT fFXORSlicefFXORSlice	PROC*              using CoreDATA	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined maskSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	bmi BumpIndexes	; special case	eor (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP	EXPORT fFBICSlicefFBICSlice	PROC*              using CoreDATA	ldy DestStartWord	; if start = finish	sty DestIndex	; then combine masks	ldx SrcStartWord	; get dest pointer into y	stx SrcIndex	; initialize index here	cpy #0	; if dest index is neg then we had to	bmi SkipMask	; dec it when it was 0Loop	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined maskSkipMask	ldy SrcIndex	; Get source word	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	bmi BumpIndexes	; special case	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	lda [SrcRef],y	iny	iny	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	iny	iny	sty DestIndex	cpy DestFinishWord	bcc Loop	beq LoopAllDone	rtl	ENDP;                COPY SLICES/FBACK.SLICES***************************************************************** FastBackSlices** These routine are	only called when a slice can be copied* from one place to	another without shifting.  Without shifting,* it works much faster since no calls to ShiftOut and ShiftSTay* need to be made.*********************************************************************************************************************************** fBFCOPYSlice** Does a backwards COPY slice without shifting.** Modification History** June 4, 1986	 SEG**     The first four lines were in the wrong order.  The y*     register needs to be left with the dest index in it*     rather than the source index.  Moreover, the Y-reg*     was incorrectly set after the ScanMask word was read.*****************************************************************	EXPORT fBFCopySlicefBFCopySlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	sty SrcIndex	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masksLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDest	ldy SrcIndex	; Get Src Index !!!! SEG 4 Jun 86	lda [SrcRef],y	; get word	dey	dey	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestIndex	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	; Get SrcIndex !!! SEG 4 Jun 86	lda [SrcRef],y	; get from before	dey	dey	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP****************************************************************** fBFORSlice** Does a backwards OR slice without shifting.** June 4, 1986	 SEG**     The first four lines were in the wrong order.  The y*     register needs to be left with the dest index in it*     rather than the source index.  Moreover, the FastWay*     through this loop did not use the	right value of Y*     for the source index.*****************************************************************	EXPORT fBFORSlicefBFORSlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	sty SrcIndex	; initialize index here	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masksLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	ldy SrcIndex	lda [SrcRef],y	; get prior word	dey	dey	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	ora (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	; Get Src Index !!!! SEG 4 Jun 86	lda [SrcRef],y	; get prior word	dey	dey	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	ora (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP****************************************************************** fBFXORSlice** Does a backwards XOR slice without shifting.** June 4, 1986	 SEG**     The first four lines were in the wrong order.  The y*     register needs to be left with the dest index in it*     rather than the source index.  Moreover, the FastWay*     through this loop did not use the	right value of Y*     for the source index.*****************************************************************	EXPORT fBFXORSlicefBFXORSlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	sty SrcIndex	; initialize index here	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masksLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	ldy SrcIndex	lda [SrcRef],y	; get prior word	dey	dey	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	eor (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	; Get Src Index !!!! SEG 4 Jun 86	lda [SrcRef],y	; get prior word	dey	dey	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP****************************************************************** fBFBICSlice** Does a backwards BIC slice without shifting.** June 4, 1986	 SEG**     The first four lines were in the wrong order.  The y*     register needs to be left with the dest index in it*     rather than the source index.  Moverover, the FastWay*     through this loop did not use the	right value of Y*     for the source index.*****************************************************************	EXPORT fBFBICSlicefBFBICSlice	PROC*              using CoreDATA	ldy SrcFinishWord	; get dest pointer into y	sty SrcIndex	; initialize index here	ldy DestFinishWord	; if start = finish	sty DestIndex	; then combine masksLoop		; 	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	ldy SrcIndex	lda [SrcRef],y	; get prior word	dey	dey	sty SrcIndex	bvc NotNot1	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot1	and CombinedMask	; and with combined	mask	ldy DestIndex	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.	bra BumpIndexesFastWay		; 	ldy SrcIndex	; Get Src Index !!!! SEG 4 Jun 86	lda [SrcRef],y	; get prior word	dey	dey	sty SrcIndex	bvc NotNot2	; check to see if should invert source	eor #$FFFF	; invert sourceNotNot2	ldy DestIndex	eor #$FFFF	and (DestRef),y	sta (DestRef),y	; and store it.BumpIndexes		; 	dey	dey	bmi AllDone	; if this is neg then we had to dec*		; start word when it was 0	sty DestIndex	cpy DestStartWord	; we are done if <=	StartWord	bcs LoopAllDone	rtl	ENDP;                copy SLICES/fast.copy***************************************************************** fRealFastCopy** This is a low level pixel transfer routines.  It copies* pixels from one scan line to another without shifting.** This routine can only be used if no shifting is needed, the regions* being clipped to are rectangular, and	there are at least 3 words* (6 bytes) to move).** This routine copies left to right.  bRealFastCopy copies from* right to left.*****************************************************************	EXPORT fRealFastCopyfRealFastCopy	PROC*              using CoreDATA;-------------------------------------------------;; First I do the left most word in the scan line;	ldy DestStartWord	; if start = finish	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDest	ldy SrcStartWord	; Get source word	lda [SrcRef],y	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestStartWord	sta (DestRef),y	; and store it.	bra MoveMiddleFastWay		; 	ldy SrcStartWord	lda [SrcRef],y	ldy DestStartWord	sta (DestRef),y	; and store it.;-------------------------------------------------;; Now we move the middle bytes.MoveMiddle		; ;-------------------------------------------------;; First I set up X to have a pointer to	the first; word I'm going to move.;;    X = SrcRef + OffsetinLineOfFirstWordToMove - StartingPointInRun;;    X = SrcRef + SrcStartWord + 2 -;                  (160 - (NumDestWords	+ 2 - 4));;      = SrcRef + SrcStartWord + 2 - 160 + NumDestWords + 2	- 4;;      = SrcRef + SrcStartWord + NumDestWords - 160;; We must remember that NumDestWords is	difference of Last and; first word so is off by 2!;;	lda SrcRef	clc	adc SrcStartWord	sec	sbc #160	clc	adc NumDestWords	tax;-------------------------------------------------;; Now I do it again	for Y.;	lda DestRef	clc	adc DestStartWord	sec	sbc #160	clc	adc NumDestWords	tay;-------------------------------------------------;; Push RTL address on stack so can get back here.;	phk	pea RightMost-1;-------------------------------------------------;; Figure out where in the move run we want to fall.;; We want to jump into the run;;    (NumDestWords + 2  - 4) * 3 bytes from the end of;	              the chute;	lda NumDestWords	; Start with num dest words	dec a	; subtract 2	dec a	pha	; put on stack	asl a	; double	adc 1,s	; add to stack so get 3 * that value	eor #$FFFF	; invert it	inc a	clc	; add to end of chute minus one	adc #fEndOfChute-1	; and do rts. Minus	one because	sta 1,s	; rts works that way.	rts;-------------------------------------------------;; Finally, we copy the rightmost word in the; line;RightMost		; 	ldy DestFinishWord	; if start = finish	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay2	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDest	ldy SrcFinishWord	; Get source word	lda [SrcRef],y	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestFinishWord	sta (DestRef),y	; and store it.	rtlFastWay2		; 	ldy SrcFinishWord	lda [SrcRef],y	ldy DestFinishWord	sta (DestRef),y	; and store it.	rtl	ENDP****************************************************************** The Razor Blade of Life** This is an extreamly fast copy routine for moving up to 156* bytes from one scan line to another.** X and Y are preset to be pointers into the scan lines* and the calling routine jumps into the middle of this run.** X and Y are calculated as follows:**     index = SrcRef + OffsetInLineOfFirstWordToMove - StartingPointInRun** where**     OffsetInLineOfFirstWordToMove = FirstWord + 2**     StartingPointInRun = 160 - NumBytesToMove*****************************************************************	EXPORT fRazorMovefRazorMove	PROC	lda |2,x	; starts at 2 because 0 can never	sta |2,y	; be moved this way	lda |4,x	sta |4,y	lda |6,x	sta |6,y	lda |8,x	sta |8,y	lda |10,x	sta |10,y	lda |12,x	sta |12,y	lda |14,x	sta |14,y	lda |16,x	sta |16,y	lda |18,x	sta |18,y	lda |20,x	sta |20,y	lda |22,x	sta |22,y	lda |24,x	sta |24,y	lda |26,x	sta |26,y	lda |28,x	sta |28,y	lda |30,x	sta |30,y	lda |32,x	sta |32,y	lda |34,x	sta |34,y	lda |36,x	sta |36,y	lda |38,x	sta |38,y	lda |40,x	sta |40,y	lda |42,x	sta |42,y	lda |44,x	sta |44,y	lda |46,x	sta |46,y	lda |48,x	sta |48,y	lda |50,x	sta |50,y	lda |52,x	sta |52,y	lda |54,x	sta |54,y	lda |56,x	sta |56,y	lda |58,x	sta |58,y	lda |60,x	sta |60,y	lda |62,x	sta |62,y	lda |64,x	sta |64,y	lda |66,x	sta |66,y	lda |68,x	sta |68,y	lda |70,x	sta |70,y	lda |72,x	sta |72,y	lda |74,x	sta |74,y	lda |76,x	sta |76,y	lda |78,x	sta |78,y	lda |80,x	sta |80,y	lda |82,x	sta |82,y	lda |84,x	sta |84,y	lda |86,x	sta |86,y	lda |88,x	sta |88,y	lda |90,x	sta |90,y	lda |92,x	sta |92,y	lda |94,x	sta |94,y	lda |96,x	sta |96,y	lda |98,x	sta |98,y	lda |100,x	sta |100,y	lda |102,x	sta |102,y	lda |104,x	sta |104,y	lda |106,x	sta |106,y	lda |108,x	sta |108,y	lda |110,x	sta |110,y	lda |112,x	sta |112,y	lda |114,x	sta |114,y	lda |116,x	sta |116,y	lda |118,x	sta |118,y	lda |120,x	sta |120,y	lda |122,x	sta |122,y	lda |124,x	sta |124,y	lda |126,x	sta |126,y	lda |128,x	sta |128,y	lda |130,x	sta |130,y	lda |132,x	sta |132,y	lda |134,x	sta |134,y	lda |136,x	sta |136,y	lda |138,x	sta |138,y	lda |140,x	sta |140,y	lda |142,x	sta |142,y	lda |144,x	sta |144,y	lda |146,x	sta |146,y	lda |148,x	sta |148,y	lda |150,x	sta |150,y	lda |152,x	sta |152,y	lda |154,x	sta |154,y	lda |156,x	sta |156,y	lda |158,x	sta |158,y	EXPORT FEndOfChuteFEndOfChute		;       	rtl	ENDP***************************************************************** bRealFastCopy** This is a low level pixel transfer routines.  It copies* pixels from one scan line to another without shifting.** This routine can only be used if no shifting is needed, the regions* being clipped to are rectangular, and	there are at least 3 words* (6 bytes) to move).** This routine copies right to left.  fRealFastCopy copies from* left to right.*****************************************************************	EXPORT bRealFastCopybRealFastCopy	PROC*              using CoreDATA;-------------------------------------------------;; First, we copy the rightmost word in the; line;	ldy DestFinishWord	; if start = finish	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay2	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDest	ldy SrcFinishWord	; Get source word	lda [SrcRef],y	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestFinishWord	sta (DestRef),y	; and store it.	bra MoveMiddleFastWay2		; 	ldy SrcFinishWord	lda [SrcRef],y	ldy DestFinishWord	sta (DestRef),y	; and store it.;-------------------------------------------------;; Now we move the middle bytes.MoveMiddle		; ;-------------------------------------------------;; First I set up X to have a pointer to	the first; word I'm going to move.;;    X = SrcRef + OffsetinLineOfFirstWordToMove - StartingPointInRun;;    X = SrcRef + SrcFinishWord - 2 -;	(NumDestWords + 2 -	4);;      = SrcRef + SrcFinishWord - 2 - NumDestWords - 2 + 4;;      = SrcRef + SrcStartWord - NumDestWords;; We must remember that NumDestWords is	difference of Last and; first word so is off by 2!;;	lda SrcRef	clc	adc SrcFinishWord	sec	sbc NumDestWords	tax;-------------------------------------------------;; Now I do it again	for Y.;	lda DestRef	clc	adc DestFinishWord	sec	sbc NumDestWords	tay;-------------------------------------------------;; Push RTL address on stack so can get back here.;	phk	pea LeftMost-1;-------------------------------------------------;; Figure out where in the move run we want to fall.;; We want to jump into the run;;    (NumDestWords + 2  - 4) * 3 bytes from the end of;	              the chute;	lda NumDestWords	; Start with num dest words	dec a	; subtract 2	dec a	pha	; put on stack	asl a	; double	adc 1,s	; add to stack so get 3 * that value	eor #$FFFF	; invert it	inc a	clc	; add to end of chute minus one	adc #bEndOfChute-1	; and do rts. Minus	one because	sta 1,s	; rts works that way.	rts;-------------------------------------------------;; Last I do the left most word in the scan line;LeftMost		; 	ldy DestStartWord	; if start = finish	lda [ScanMaskRef],y	cmp #$FFFF	beq FastWay	sta CombinedMask	; put in combined mask	eor #$FFFF	; invert combined mask	and (DestRef),y	sta NotMaskAndDest	ldy SrcStartWord	; Get source word	lda [SrcRef],y	and CombinedMask	; and with combined	mask	ora NotMaskAndDest	; merge with original part that stays	ldy DestStartWord	sta (DestRef),y	; and store it.	rtlFastWay		; 	ldy SrcStartWord	lda [SrcRef],y	ldy DestStartWord	sta (DestRef),y	; and store it.	rtl	ENDP****************************************************************** The Other Razor Blade of Life** This is an extreamly fast copy routine for moving up to 156* bytes from one scan line to another (from right to left).** X and Y are preset to be pointers into the scan lines* and the calling routine jumps into the middle of this run.** X and Y are calculated as follows:**     index = SrcRef + OffsetInLineOfFirstWordToMove - StartingPointInRun** where**     OffsetInLineOfFirstWordToMove = LASTWord - 2**     StartingPointInRun = NumBytesToMove*****************************************************************	EXPORT bRazorMovebRazorMove	PROC	lda |158,x	sta |158,y	lda |156,x	sta |156,y	lda |154,x	sta |154,y	lda |152,x	sta |152,y	lda |150,x	sta |150,y	lda |148,x	sta |148,y	lda |146,x	sta |146,y	lda |144,x	sta |144,y	lda |142,x	sta |142,y	lda |140,x	sta |140,y	lda |138,x	sta |138,y	lda |136,x	sta |136,y	lda |134,x	sta |134,y	lda |132,x	sta |132,y	lda |130,x	sta |130,y	lda |128,x	sta |128,y	lda |126,x	sta |126,y	lda |124,x	sta |124,y	lda |122,x	sta |122,y	lda |120,x	sta |120,y	lda |118,x	sta |118,y	lda |116,x	sta |116,y	lda |114,x	sta |114,y	lda |112,x	sta |112,y	lda |110,x	sta |110,y	lda |108,x	sta |108,y	lda |106,x	sta |106,y	lda |104,x	sta |104,y	lda |102,x	sta |102,y	lda |100,x	sta |100,y	lda |98,x	sta |98,y	lda |96,x	sta |96,y	lda |94,x	sta |94,y	lda |92,x	sta |92,y	lda |90,x	sta |90,y	lda |88,x	sta |88,y	lda |86,x	sta |86,y	lda |84,x	sta |84,y	lda |82,x	sta |82,y	lda |80,x	sta |80,y	lda |78,x	sta |78,y	lda |76,x	sta |76,y	lda |74,x	sta |74,y	lda |72,x	sta |72,y	lda |70,x	sta |70,y	lda |68,x	sta |68,y	lda |66,x	sta |66,y	lda |64,x	sta |64,y	lda |62,x	sta |62,y	lda |60,x	sta |60,y	lda |58,x	sta |58,y	lda |56,x	sta |56,y	lda |54,x	sta |54,y	lda |52,x	sta |52,y	lda |50,x	sta |50,y	lda |48,x	sta |48,y	lda |46,x	sta |46,y	lda |44,x	sta |44,y	lda |42,x	sta |42,y	lda |40,x	sta |40,y	lda |38,x	sta |38,y	lda |36,x	sta |36,y	lda |34,x	sta |34,y	lda |32,x	sta |32,y	lda |30,x	sta |30,y	lda |28,x	sta |28,y	lda |26,x	sta |26,y	lda |24,x	sta |24,y	lda |22,x	sta |22,y	lda |20,x	sta |20,y	lda |18,x	sta |18,y	lda |16,x	sta |16,y	lda |14,x	sta |14,y	lda |12,x	sta |12,y	lda |10,x	sta |10,y	lda |8,x	sta |8,y	lda |6,x	sta |6,y	lda |4,x	sta |4,y	lda |2,x	sta |2,y	EXPORT bEndOfChutebEndOfChute		;       	rtl	ENDP	END